{#- The header prints doc.company (the Company DOCNAME) while the emails and
    the dealer portal print brand.name (Company.company_name). They are the
    same string on both stores today; keeping doc.company here is deliberate,
    because changing it would have to be re-proved byte-identical against the
    receipt this store printed before. If a store ever renames itself without
    renaming the record, switch this to brand.name and re-run that check. -#}
{%- set brand = company_brand(doc.company) -%}
{#- Negative ticket (trade-ins exceed the goods, the store pays the customer; CPA ruling 2026-10-06):
    the totals read Items sold / Trade-in allowance / each tax row (0.00) / Total, then what was paid out and how.
    The tax line prints even at 0.00 — the credit is shown separately so the allowance is documented
    (TX Tax Code §151.007(c)). Every other invoice prints exactly as before. -#}
{%- set _ti = namespace(goods=0, credit=0) -%}
{%- for i in doc.items -%}{%- if i.item_code == "TRADE-IN-CREDIT" -%}{%- set _ti.credit = _ti.credit + i.amount -%}{%- else -%}{%- set _ti.goods = _ti.goods + i.amount -%}{%- endif -%}{%- endfor -%}
{%- set _due = doc.rounded_total or doc.grand_total -%}
{%- set _payout = (0 - _due) if (_due < 0 and not doc.is_return and _ti.credit < 0) else 0 -%}
<div style="font-family:-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;color:#1a1a1a;font-size:13px;line-height:1.55;max-width:660px;margin:0 auto;padding:4px;">

  <div style="text-align:center;padding:2px 0 12px;border-bottom:2px solid #111;">
    {% if brand.logo_url %}<img src="{{ brand.logo_url }}" style="height:54px;">{% endif %}
    <div style="font-size:18px;font-weight:800;letter-spacing:1.5px;margin-top:8px;color:#111;text-transform:uppercase;">{{ doc.company }}</div>
    {% if brand.address_line %}<div style="font-size:11px;color:#777;margin-top:4px;">{{ brand.address_line }}</div>{% endif %}
  </div>

  <table style="width:100%;border-collapse:collapse;margin-top:16px;">
    <tr>
      <td style="font-size:13px;font-weight:700;letter-spacing:2px;text-transform:uppercase;color:#111;">{{ "Transfer Receipt" if doc.get("is_ffl_transfer") else "Sales Receipt" }}</td>
      <td style="text-align:right;font-size:12px;color:#555;"><strong style="color:#111;">{{ doc.name }}</strong>&nbsp;&middot;&nbsp;{{ frappe.utils.formatdate(doc.posting_date, "MMMM d, yyyy") }}</td>
    </tr>
  </table>

  <div style="margin:18px 0 6px;">
    <span style="color:#999;font-size:11px;text-transform:uppercase;letter-spacing:1px;">Billed to</span>
    <div style="font-size:15px;font-weight:600;margin-top:2px;">{{ doc.customer_name }}</div>
  </div>

  <table style="width:100%;border-collapse:collapse;margin-top:14px;">
    <thead>
      <tr style="border-bottom:2px solid #111;color:#777;font-size:10px;text-transform:uppercase;letter-spacing:.8px;">
        <th style="text-align:left;padding:8px 6px;">Item</th>
        <th style="text-align:center;padding:8px 6px;width:56px;">Qty</th>
        <th style="text-align:right;padding:8px 6px;width:110px;">Price</th>
        <th style="text-align:right;padding:8px 6px;width:110px;">Amount</th>
      </tr>
    </thead>
    <tbody>
      {% for item in doc.items %}
      <tr style="border-bottom:1px solid #eee;">
        <td style="padding:11px 6px;vertical-align:top;">
          <div style="font-weight:600;">{{ item.item_name }}</div>
          {% if item.item_code and item.item_code != item.item_name %}<div style="color:#999;font-size:11px;margin-top:1px;">{{ item.item_code }}</div>{% endif %}
          {% if item.serial_no %}<div style="color:#999;font-size:11px;margin-top:1px;">SN: {{ item.serial_no | replace('\n', ', ') }}</div>{% endif %}
        </td>
        <td style="text-align:center;padding:11px 6px;vertical-align:top;">{{ (item.qty | int) if item.qty == (item.qty | int) else item.qty }}</td>
        <td style="text-align:right;padding:11px 6px;vertical-align:top;color:#555;">{{ item.get_formatted("rate") }}</td>
        <td style="text-align:right;padding:11px 6px;vertical-align:top;font-weight:600;">{{ item.get_formatted("amount") }}</td>
      </tr>
      {% endfor %}
    </tbody>
  </table>

  <table style="width:100%;margin-top:16px;border-collapse:collapse;">
    {% if _payout %}
    <tr><td style="text-align:right;padding:3px 6px;color:#777;">Items sold</td><td style="text-align:right;padding:3px 6px;width:130px;">{{ frappe.utils.fmt_money(_ti.goods, currency=doc.currency) }}</td></tr>
    <tr><td style="text-align:right;padding:3px 6px;color:#777;">Trade-in allowance</td><td style="text-align:right;padding:3px 6px;">{{ frappe.utils.fmt_money(_ti.credit, currency=doc.currency) }}</td></tr>
    {#- Each tax row prints as itself (sales tax, shipping, freight tax): a lump "Sales tax" would fold the
        shipping charge into the tax. No rows at all still prints the 0.00 — the credit is shown separately. -#}
    {% if not doc.taxes %}
    <tr><td style="text-align:right;padding:3px 6px;color:#777;">Sales tax</td><td style="text-align:right;padding:3px 6px;">{{ frappe.utils.fmt_money(0, currency=doc.currency) }}</td></tr>
    {% endif %}
    {%- set ship = inclusive_shipping_lines(doc) %}
    {% for tax in doc.taxes if not (ship and tax.idx in ship.taxes) %}
    {%- set gross = ship and tax.idx == ship.freight %}
    <tr><td style="text-align:right;padding:3px 6px;color:#777;">{{ tax.description }}{% if gross %} (sales tax included){% endif %}</td><td style="text-align:right;padding:3px 6px;">{{ frappe.utils.fmt_money(ship.gross, currency=doc.currency) if gross else tax.get_formatted("tax_amount") }}</td></tr>
    {% endfor %}
    {% else %}
    {% if doc.total_taxes_and_charges %}
    <tr><td style="text-align:right;padding:3px 6px;color:#777;">Subtotal</td><td style="text-align:right;padding:3px 6px;width:130px;">{{ doc.get_formatted("net_total") }}</td></tr>
    {#- Shipping that includes its sales tax (CPA ruling 2026-09-26): the freight
        tax rows stay off the receipt and the freight row prints what the customer
        paid (freight + its tax, signed — a credit note prints it negative), saying
        the tax is included, so the lines still add up to the Total. Rows are picked
        out the way the freight hook picks them (inclusive_shipping_lines); every
        other invoice prints its rows as before. -#}
    {%- set ship = inclusive_shipping_lines(doc) %}
    {% for tax in doc.taxes if not (ship and tax.idx in ship.taxes) %}
    {%- set gross = ship and tax.idx == ship.freight %}
    <tr><td style="text-align:right;padding:3px 6px;color:#777;">{{ tax.description }}{% if gross %} (sales tax included){% endif %}</td><td style="text-align:right;padding:3px 6px;">{{ frappe.utils.fmt_money(ship.gross, currency=doc.currency) if gross else tax.get_formatted("tax_amount") }}</td></tr>
    {% endfor %}
    {% endif %}
    {% endif %}
    <tr>
      <td style="text-align:right;padding:11px 6px;font-size:16px;font-weight:800;border-top:2px solid #111;">Total</td>
      <td style="text-align:right;padding:11px 6px;font-size:16px;font-weight:800;border-top:2px solid #111;width:130px;">{{ doc.get_formatted("grand_total") }}</td>
    </tr>
    {% if _payout %}
    <tr>
      <td style="text-align:right;padding:8px 6px;font-size:15px;font-weight:700;">Paid to customer{% if doc.get("ffl_trade_in_payout_method") %} ({{ doc.ffl_trade_in_payout_method | e }}{% if doc.get("ffl_trade_in_payout_reference") %}, {{ doc.ffl_trade_in_payout_reference | e }}{% endif %}){% endif %}</td>
      <td style="text-align:right;padding:8px 6px;font-size:15px;font-weight:700;width:130px;">{{ frappe.utils.fmt_money(_payout, currency=doc.currency) }}</td>
    </tr>
    {% endif %}
  </table>

  <div style="margin-top:40px;padding-top:18px;border-top:1px solid #eee;text-align:center;color:#999;font-size:12px;">
    Thank you for your business.
  </div>
  {% if brand.footer_note %}<div style="margin-top:12px;text-align:center;color:#b00020;font-size:11px;font-weight:600;line-height:1.5;">
    {{ brand.footer_note | replace('\n', '<br>\n    ') }}
  </div>{% endif %}

</div>

